import{_ as l,a0 as o,w as r,s as d,ao as t,I as i,x as s,a1 as e,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"编程基础：Java 中的输入和输出 | LCTT x X-CMD","titleTemplate":false,"description":"编程基础：Java 中的输入和输出 | LCTT (202107) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"编程基础：Java 中的输入和输出 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"编程基础：Java 中的输入和输出 | LCTT (202107) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202107/20210317 Programming 101- Input and output with Java","title":"编程基础：Java 中的输入和输出","tag":"202107","desc":""},"relativePath":"202107/20210317 Programming 101- Input and output with Java.md","filePath":"[post].md"}'),c={name:"202107/20210317 Programming 101- Input and output with Java.md"};function u(h,a,g,m,v,k){const n=o("Link");return r(),d("div",null,[a[24]||(a[24]=t('<h1 id="编程基础-java-中的输入和输出" tabindex="-1">编程基础：Java 中的输入和输出 <a class="header-anchor" href="#编程基础-java-中的输入和输出" aria-label="Permalink to “编程基础：Java 中的输入和输出”">​</a></h1><blockquote><p>学习 Java 如何外理数据的读与写。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202107/27/101854by7yizpokqyo77kk.jpg" alt=""></p><p>当你写一个程序时，你的应用程序可能需要读取和写入存储在用户计算机上的文件。这在你想加载或存储配置选项，你需要创建日志文件，或你的用户想要保存工作以待后用的情况下是很常见的。每种语言处理这项任务的方式都有所不同。本文演示了如何用 Java 处理数据文件。</p><h3 id="安装-java" tabindex="-1">安装 Java <a class="header-anchor" href="#安装-java" aria-label="Permalink to “安装 Java”">​</a></h3>',5)),i("p",null,[a[1]||(a[1]=s("不管你的计算机是什么平台，你都可以从 ",-1)),e(n,{href:"https://adoptopenjdk.net"},{default:p(()=>[...a[0]||(a[0]=[s("AdoptOpenJDK",-1)])]),_:1}),a[2]||(a[2]=s(" 安装 Java。这个网站提供安全和开源的 Java 构建。在 Linux 上，你的软件库中也可能找到 AdoptOpenJDK 的构建。",-1))]),a[25]||(a[25]=i("p",null,"我建议你使用最新的长期支持（LTS）版本。最新的非 LTS 版本对希望尝试最新 Java 功能的开发者来说是最好的，但它很可能超过大多数用户所安装的版本 —— 要么是系统上默认安装的，要么是以前为其他 Java 应用安装的。使用 LTS 版本可以确保你与大多数用户所安装的版本保持一致。",-1)),i("p",null,[a[4]||(a[4]=s("一旦你安装好了 Java，就可以打开你最喜欢的文本编辑器并准备开始写代码了。你可能还想要研究一下 ",-1)),e(n,{href:"https://opensource.com/article/20/7/ide-java"},{default:p(()=>[...a[3]||(a[3]=[s("Java 集成开发环境",-1)])]),_:1}),a[5]||(a[5]=s("。BlueJ 是新程序员的理想选择，而 Eclipse 和 Netbeans 对中级和有经验的编码者更友好。",-1))]),a[26]||(a[26]=t(`<h3 id="利用-java-读取文件" tabindex="-1">利用 Java 读取文件 <a class="header-anchor" href="#利用-java-读取文件" aria-label="Permalink to “利用 Java 读取文件”">​</a></h3><p>Java 使用 <code>File</code> 类来加载文件。</p><p>这个例子创建了一个叫 <code>Ingest</code> 的类来读取文件中数据。当你要在 Java 中打开一个文件时，你创建了一个 <code>Scanner</code> 对象，它可以逐行扫描你提供的文件。事实上，<code>Scanner</code> 与文本编辑器中的光标是相同的概念，这样你可以用 <code>Scanner</code> 的一些方法（如 <code>nextLine</code>）来控制这个“光标”以进行读写。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import java.io.File;</span></span>
<span class="line"><span>import java.util.Scanner;</span></span>
<span class="line"><span>import java.io.FileNotFoundException;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class Ingest {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>      try {</span></span>
<span class="line"><span>          File myFile = new File(&quot;example.txt&quot;);</span></span>
<span class="line"><span>          Scanner myScanner = new Scanner(myFile);</span></span>
<span class="line"><span>          while (myScanner.hasNextLine()) {</span></span>
<span class="line"><span>              String line = myScanner.nextLine();</span></span>
<span class="line"><span>              System.out.println(line);</span></span>
<span class="line"><span>          }</span></span>
<span class="line"><span>          myScanner.close();</span></span>
<span class="line"><span>      } catch (FileNotFoundException ex) {</span></span>
<span class="line"><span>          ex.printStackTrace();  </span></span>
<span class="line"><span>      } //try</span></span>
<span class="line"><span>    } //main</span></span>
<span class="line"><span>} //class</span></span></code></pre></div><p>这段代码首先在假设存在一个名为 <code>example.txt</code> 的文件的情况下创建了变量 <code>myfile</code>。如果该文件不存在，Java 就会“抛出一个异常”（如它所说的，这意味着它在你试图做的事情中发现了一个错误），这个异常是被非常特定的 <code>FileNotFoundException</code> 类所“捕获”。事实上，有一个专门的类来处理这个明确的错误，这说明这个错误是多么常见。</p><p>接下来，它创建了一个 <code>Scanner</code> 并将文件加载到其中。我把它叫做 <code>myScanner</code>，以区别于它的通用类模板。接着，一个 <code>while</code> 循环将 <code>myScanner</code> 逐行送入文件中，只要 <em>存在</em> 下一行。这就是 <code>hasNextLine</code> 方法的作用：它检测“光标”之后是否还有数据。你可以通过在文本编辑器中打开一个文件来模拟这个过程：你的光标从文件的第一行开始，你可以用键盘控制光标来向下扫描文件，直到你走完了所有的行。</p><p><code>while</code> 循环创建了一个变量 <code>line</code>，并将文件当前行的数据分配给它。然后将 <code>line</code> 的内容打印出来以提供反馈。一个更有用的程序可能会解析每一行的内容，从而提取它所包含的任何重要数据。</p><p>在这个过程结束时，关闭 <code>myScanner</code> 对象。</p><h3 id="运行代码" tabindex="-1">运行代码 <a class="header-anchor" href="#运行代码" aria-label="Permalink to “运行代码”">​</a></h3><p>将你的代码保存到 <code>Ingest.java</code> 文件（这是一个 Java 惯例，将类名的首字母大写，并以类名来命名相应的文件）。如果你试图运行这个简单的应用程序，你可能会接收到一个错误信息，这是因为还没有 <code>example.txt</code> 文件供应用程序加载:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java ./Ingest.java</span></span>
<span class="line"><span>java.io.FileNotFoundException:</span></span>
<span class="line"><span>example.txt (No such file or directory)</span></span></code></pre></div><p>正好可以编写一个将数据写入文件的 Java 应用程序，多么完美的时机！</p><h3 id="利用-java-将数据写入文件" tabindex="-1">利用 Java 将数据写入文件 <a class="header-anchor" href="#利用-java-将数据写入文件" aria-label="Permalink to “利用 Java 将数据写入文件”">​</a></h3><p>无论你是存储用户使用你的应用程序创建的数据，还是仅仅存储关于用户在应用程序中做了什么的元数据（例如，游戏保存或最近播放的歌曲），有很多很好的理由来存储数据供以后使用。在 Java 中，这是通过 <code>FileWriter</code> 类实现的，这次先打开一个文件，向其中写入数据，然后关闭该文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import java.io.FileWriter;</span></span>
<span class="line"><span>import java.io.IOException;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public class Exgest {</span></span>
<span class="line"><span>  public static void main(String[] args) {</span></span>
<span class="line"><span>    try {</span></span>
<span class="line"><span>        FileWriter myFileWriter = new FileWriter(&quot;example.txt&quot;, true);</span></span>
<span class="line"><span>        myFileWriter.write(&quot;Hello world\\n&quot;);</span></span>
<span class="line"><span>        myFileWriter.close();</span></span>
<span class="line"><span>    } catch (IOException ex) {</span></span>
<span class="line"><span>        System.out.println(ex);</span></span>
<span class="line"><span>    } // try</span></span>
<span class="line"><span>  } // main</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这个类的逻辑和流程与读取文件类似。但它不是一个 <code>Scanner</code>，而是以一个文件的名字为参数创建的一个 <code>FileWriter</code> 对象。<code>FileWriter</code> 语句末尾的 <code>true</code> 标志告诉 <code>FileWriter</code> 将文本 <em>追加</em> 到文件的末尾。要覆盖一个文件的内容，请移除 <code>true</code> 标志。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>\`FileWriter myFileWriter = new FileWriter(&quot;example.txt&quot;, true);\`</span></span></code></pre></div><p>因为我在向文件中写入纯文本，所以我在写入文件的数据（<code>Hello world</code>）的结尾处手动添加了换行符（<code>\\n</code>）。</p><h3 id="试试代码" tabindex="-1">试试代码 <a class="header-anchor" href="#试试代码" aria-label="Permalink to “试试代码”">​</a></h3><p>将这段代码保存到 <code>Exgest.java</code> 文件，遵循 Java 的惯例，使文件名为与类名相匹配。</p><p>既然你已经掌握了用 Java 创建和读取数据的方法，你可以按相反的顺序尝试运行你的新应用程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Ingest.java</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>因为程序是把数据追加到文件末尾，所以你可以重复执行你的应用程序以多次写入数据，只要你想把更多的数据添加到你的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Exgest.java</span></span>
<span class="line"><span>$ java ./Ingest.java</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>Hello world</span></span>
<span class="line"><span>$</span></span></code></pre></div><h3 id="java-和数据" tabindex="-1">Java 和数据 <a class="header-anchor" href="#java-和数据" aria-label="Permalink to “Java 和数据”">​</a></h3><p>你不会经常向文件中写入原始文本；事实上，你可能会使用一个其它的类库以写入特定的格式。例如，你可能使用 XML 类库来写复杂的数据，使用 INI 或 YAML 类库来写配置文件，或者使用各种专门类库来写二进制格式，如图像或音频。</p>`,26)),i("p",null,[a[7]||(a[7]=s("更完整的信息，请参阅 ",-1)),e(n,{href:"https://access.redhat.com/documentation/en-us/openjdk/11/"},{default:p(()=>[...a[6]||(a[6]=[s("OpenJDK 文档",-1)])]),_:1}),a[8]||(a[8]=s("。",-1))]),a[27]||(a[27]=i("hr",null,null,-1)),i("p",null,[a[10]||(a[10]=s("via: ",-1)),e(n,{href:"https://opensource.com/article/21/3/io-java"},{default:p(()=>[...a[9]||(a[9]=[s("https://opensource.com/article/21/3/io-java",-1)])]),_:1})]),i("p",null,[a[15]||(a[15]=s("作者：",-1)),e(n,{href:"https://opensource.com/users/seth"},{default:p(()=>[...a[11]||(a[11]=[s("Seth Kenlon",-1)])]),_:1}),a[16]||(a[16]=s(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:p(()=>[...a[12]||(a[12]=[s("lujun9972",-1)])]),_:1}),a[17]||(a[17]=s(" 译者：",-1)),e(n,{href:"https://github.com/piaoshi"},{default:p(()=>[...a[13]||(a[13]=[s("piaoshi",-1)])]),_:1}),a[18]||(a[18]=s(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:p(()=>[...a[14]||(a[14]=[s("wxy",-1)])]),_:1})]),i("p",null,[a[21]||(a[21]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...a[19]||(a[19]=[s("LCTT",-1)])]),_:1}),a[22]||(a[22]=s(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:p(()=>[...a[20]||(a[20]=[s("Linux中国",-1)])]),_:1}),a[23]||(a[23]=s(" 荣誉推出",-1))])])}const y=l(c,[["render",u]]);export{f as __pageData,y as default};
